const express = require('express');
const { expressjwt: jwt } = require('express-jwt');
const jwksRsa = require('jwks-rsa');
const knex = require('knex')({ client: 'pg', connection: process.env.DATABASE_URL });

const app = express();

const checkJwt = jwt({
  secret: jwksRsa.expressJwtSecret({
    cache: true,
    rateLimit: true,
    jwksRequestsPerMinute: 10,
    jwksUri: (header) => `https://${header.kid_tenant || 'default'}.auth.domain.com/.well-known/jwks.json`
  }),
  algorithms: ['RS256']
});

app.get('/api/tenants/:tenantSlug/audit-events', checkJwt, async (req, res) => {
  const { tenantSlug } = req.params;

  // Assert that authenticated token belongs to the requested tenantSlug
  if (req.auth.tenant_slug !== tenantSlug) {
    return res.status(403).json({ error: 'Access denied: token not scoped for this tenant' });
  }

  const events = await knex('audit_logs').where({ tenant_slug: tenantSlug }).limit(100);
  return res.json({ tenantSlug, count: events.length, events });
});

module.exports = app;
